// Rotation matrix around the X axis.
mat3 rotateX(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(1, 0, 0),
        vec3(0, c, -s),
        vec3(0, s, c)
    );
}

// Rotation matrix around the Y axis.
mat3 rotateY(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(c, 0, s),
        vec3(0, 1, 0),
        vec3(-s, 0, c)
    );
}

// Rotation matrix around the Z axis.
mat3 rotateZ(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(c, -s, 0),
        vec3(s, c, 0),
        vec3(0, 0, 1)
    );
}



float opSmoothUnion( float d1, float d2, float k )
{
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h);
}

float sdBox( vec3 p, vec3 b )
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

float sdf (vec3 p) {
    //return opSmoothUnion(
    //    length(p-vec3(0., -0.5, 0.)) - 1.0,
    //    length(p-vec3(0.,  0.5, 0.)) - 1.0,
    //    0.2
    //);
    return sdBox(rotateX(cos(iTime+p.y)) * rotateY(sin(iTime+p.y)) * p, vec3(1., 1., 1.));
}

vec3 calcNormal (vec3 p) {
    vec2 e = vec2(1.0, -1.0) * 0.0005;
    return normalize(
        e.xyy * sdf(p + e.xyy) +
        e.yyx * sdf(p + e.yyx) +
        e.yxy * sdf(p + e.yxy) +
        e.xxx * sdf(p + e.xxx));
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord / iResolution.xy;
    vec2 muv = iMouse.xy / iResolution.xy;

    vec3 p = vec3(vec2((uv.x*2.-1.)*iResolution.x/iResolution.y, uv.y*2.-1.), 0.)*2.;
    vec3 eye = vec3(0., 0., 10.);

    p = rotateY(iMouse.x*0.01+3.14) * rotateX(-iMouse.y*0.01+3.14) * p;
    eye = rotateY(iMouse.x*0.01+3.14) * rotateX(-iMouse.y*0.01+3.14) * eye;

    vec3 dir = normalize(p - eye);

    float dist = 100000000000000000.;
    float depth = 0.;
    for (int i=0; i<16; i++) {
        p = eye + dir*depth;
        dist = min(dist, sdf(p));
        if (dist < 0.01) break;
        depth += dist;
    }


    vec3 light = vec3(1., 1., 1.);
    float f = clamp(dot(calcNormal(p), light), 0., 1.);
    vec3 col = vec3(f) * exp(-5.*dist) * calcNormal(p);;

    // Output to screen
    //fragColor = vec4(vec3(smoothstep(-0.01, 0.01, r)),1.0);
    //fragColor = vec4(vec3(exp(-dist)),1.0);
    fragColor = vec4(col,1.0);
}
